## 2. Обновляем `main.py` — применяем стиль глобально

```python
import sys
from PyQt6.QtWidgets import QApplication

from core.smartshell_client import SmartShellClient
from gui.main_window import MainWindow
from gui.styles import apply_global_style   # ← НОВЫЙ ИМПОРТ


def main():
    app = QApplication(sys.argv)

    # ПРИМЕНЯЕМ SMARTSHELL-СТИЛЬ
    apply_global_style(app)

    client = SmartShellClient()
    window = MainWindow(client)
    window.show()

    sys.exit(app.exec())


if __name__ == "__main__":
    main()
```

