class FetchWorker(QThread):
    finished = pyqtSignal(int, list)
    error = pyqtSignal(int, str)

    def __init__(self, client: SmartShellClient, search: str, request_id: int):
        super().__init__()
        self.client = client
        self.search = search
        self.request_id = request_id

    def run(self):
        try:
            import time
            t0 = time.time()
            items = self.client.fetch_goods(self.search)
            elapsed = time.time() - t0
            print(f"[UI] Запрос #{self.request_id} ('{self.search}') — {len(items)} товаров за {elapsed:.2f}с")
            self.finished.emit(self.request_id, items)
        except Exception as e:
            self.error.emit(self.request_id, str(e))


